def drive(me, enemy, arena):
    b = bearing_to(enemy.x, enemy.y)
    t = b / 60.0
    if t > 1:
        t = 1
    if t < -1:
        t = -1
    return (1 - t, 1 + t)

def weapons(me, enemy, arena):
    d = distance_to(enemy.x, enemy.y)
    cmds = [spin("back", 3000)]
    if d < 1.0:
        cmds.append(grab("front"))
    else:
        cmds.append(release("front"))
    return cmds

def drive(me, enemy, arena):
    if me.inverted or me.on_side or me.airborne or me.lifted:
        return (0, 0)
    if me.held:
        return (1.0, 1.0)
    plan = me.memory.get("flipplan", 0)
    b = bearing_to(enemy.x, enemy.y)
    d = distance_to(enemy.x, enemy.y)
    if plan:
        if abs(b) < 100:
            if b > 0:
                return (0.9, -0.9)
            return (-0.9, 0.9)
        if d > 0.45:
            return (-1.0, -1.0)
        return (0.0, 0.0)
    r = sqrt(me.x * me.x + me.y * me.y)
    if r > 4.6:
        tx = enemy.x * 0.5
        ty = enemy.y * 0.5
    else:
        tx = enemy.x
        ty = enemy.y
    b = bearing_to(tx, ty)
    if b > 15:
        return (0.8, -0.8)
    if b < -15:
        return (-0.8, 0.8)
    return (1.0, 1.0)


def weapons(me, enemy, arena):
    cmds = []
    w = me.weapons
    sp = w.get("front")
    if sp is not None and sp.get("type") == "spinner":
        cmds.append(spin("front", sp.get("max_rpm", 0)))
    fl = w.get("back")
    has_flip = (fl is not None and fl.get("type") == "flipper"
                and fl.get("ready") and fl.get("shots_left", 0) > 0)
    if me.inverted:
        if has_flip:
            cmds.append(self_right())
        return cmds
    if not has_flip:
        return cmds
    b = bearing_to(enemy.x, enemy.y)
    d = distance_to(enemy.x, enemy.y)
    if d < 1.7 and abs(b) > 110 and not enemy.airborne and not enemy.inverted and not enemy.on_side:
        cmds.append(flip("back"))
        me.memory["flipplan"] = 0
    elif arena.time_left < 18 and d < 2.6 and not enemy.airborne and not enemy.inverted and not enemy.on_side:
        me.memory["flipplan"] = 1
    return cmds

