def drive(me, enemy, arena):
    if me.lifted or me.on_side:
        return (0, 0)
    if me.held:
        return (1.0, 1.0)
    r = sqrt(me.x * me.x + me.y * me.y)
    b = bearing_to(enemy.x, enemy.y)
    d = distance_to(enemy.x, enemy.y)
    if r > 5.3:
        bc = bearing_to(0.0, 0.0)
        if bc > 15:
            return (0.9, -0.9)
        if bc < -15:
            return (-0.9, 0.9)
        return (1.0, 1.0)
    if b > 12:
        return (0.8, -0.8)
    if b < -12:
        return (-0.8, 0.8)
    if d > 0.8:
        return (1.0, 1.0)
    return (0.8, 0.8)


def weapons(me, enemy, arena):
    cmds = []
    fl = me.weapons.get("front")
    if fl is None or fl.get("type") != "flipper":
        return cmds
    ready = bool(fl.get("ready")) and fl.get("shots_left", 0) > 0
    if me.righting or me.airborne or me.on_side:
        return cmds
    if me.inverted:
        if ready:
            cmds.append(self_right())
        return cmds
    if not ready:
        return cmds
    if enemy.airborne or enemy.inverted or enemy.on_side:
        return cmds
    b = bearing_to(enemy.x, enemy.y)
    d = distance_to(enemy.x, enemy.y)
    if d < 0.85 and abs(b) < 40:
        cmds.append(flip("front"))
    return cmds
